Here's a C implementation of a simple arena allocator with alignment support:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Alignment macros
#define ARENA_ALIGNMENT 16  // Default alignment (16 bytes)

// Calculate alignment padding
#define ALIGN_UP(size, alignment) (((size) + (alignment) - 1) & ~((alignment) - 1))
#define ALIGN_DOWN(size, alignment) ((size) & ~((alignment) - 1))

typedef struct Arena {
    unsigned char *buffer;    // Memory buffer
    size_t capacity;          // Total capacity in bytes
    size_t offset;            // Current offset in buffer (next free position)
} Arena;

// Create an arena with the given capacity
Arena *arena_create(size_t capacity) {
    Arena *arena = (Arena *)malloc(sizeof(Arena));
    if (!arena) return NULL;

    arena->buffer = (unsigned char *)malloc(capacity);
    if (!arena->buffer) {
        free(arena);
        return NULL;
    }

    arena->capacity = capacity;
    arena->offset = 0;

    return arena;
}

// Allocate memory from the arena with alignment
void *arena_alloc(Arena *arena, size_t size) {
    if (!arena || !arena->buffer) return NULL;

    // Align the size up to the next multiple of ARENA_ALIGNMENT
    size_t aligned_size = ALIGN_UP(size, ARENA_ALIGNMENT);

    // Check if we have enough space
    if (arena->offset + aligned_size > arena->capacity) {
        return NULL;  // Out of memory
    }

    // Get current pointer and advance the offset
    void *ptr = arena->buffer + arena->offset;
    arena->offset += aligned_size;

    return ptr;
}

// Reset the arena (marks all memory as free)
void arena_reset(Arena *arena) {
    if (arena) {
        arena->offset = 0;
    }
}

// Destroy the arena and free all memory
void arena_destroy(Arena *arena) {
    if (arena) {
        if (arena->buffer) {
            free(arena->buffer);
        }
        free(arena);
    }
}

// Example usage
int main() {
    // Create an arena with 1024 bytes capacity
    Arena *arena = arena_create(1024);
    if (!arena) {
        fprintf(stderr, "Failed to create arena\n");
        return 1;
    }

    printf("Arena created successfully\n");
    printf("Capacity: %zu bytes\n", arena->capacity);

    // Allocate some memory
    int *int_ptr = (int *)arena_alloc(arena, sizeof(int));
    if (int_ptr) {
        *int_ptr = 42;
        printf("Allocated int: %d at %p\n", *int_ptr, (void *)int_ptr);
    }

    // Allocate an array
    int *array = (int *)arena_alloc(arena, 5 * sizeof(int));
    if (array) {
        for (int i = 0; i < 5; i++) {
            array[i] = i * 10;
        }
        printf("Allocated array: ");
        for (int i = 0; i < 5; i++) {
            printf("%d ", array[i]);
        }
        printf(" at %p\n", (void *)array);
    }

    // Allocate a struct
    typedef struct {
        double x, y, z;
        char name[32];
    } Point;

    Point *point = (Point *)arena_alloc(arena, sizeof(Point));
    if (point) {
        point->x = 1.0;
        point->y = 2.0;
        point->z = 3.0;
        strcpy(point->name, "Origin");
        printf("Allocated Point: (%.1f, %.1f, %.1f) '%s' at %p\n",
               point->x, point->y, point->z, point->name, (void *)point);
    }

    printf("\nArena offset after allocations: %zu bytes\n", arena->offset);

    // Reset the arena
    arena_reset(arena);
    printf("Arena reset. Offset: %zu bytes\n", arena->offset);

    // We can allocate again
    int *new_int = (int *)arena_alloc(arena, sizeof(int));
    if (new_int) {
        *new_int = 100;
        printf("After reset: Allocated int: %d at %p\n", *new_int, (void *)new_int);
    }

    // Destroy the arena
    arena_destroy(arena);
    printf("\nArena destroyed\n");

    return 0;
}
```

**Key features:**

1. **Memory management**: The arena allocates a single contiguous block of memory upfront, avoiding repeated `malloc` calls.

2. **Alignment**: All allocations are aligned to `ARENA_ALIGNMENT` (16 bytes by default) using the `ALIGN_UP` macro.

3. **Efficiency**: Allocation is O(1) - just bumping a pointer. No fragmentation issues.

4. **Simplicity**: Clear and straightforward implementation using only standard C library functions.

**How it works:**

- `arena_create`: Allocates an arena structure and its memory buffer using `malloc`.
- `arena_alloc`: Returns the next available aligned memory block from the arena, advancing the offset.
- `arena_reset`: Simply resets the offset to 0, effectively "freeing" all allocations at once.
- `arena_destroy`: Frees both the arena structure and its memory buffer.

**Memory layout:**

```
[ Arena Structure ] → [ Memory Buffer ]
                           ↓
                      [ Next free ]
                      [ Offset ]→ → [ Allocated memory ]
                      [ [ Padding ] ]
                      [ Allocated memory ]
                      ...
```

This arena allocator is particularly useful in scenarios where many small allocations are needed and then freed all at once (like parsing, game object creation, or temporary calculations).

# C Hash Table Implementation (Open Addressing, Linear Probing)

Here's a complete hash table implementation with all the requested features:

```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* Hash table entry states */
typedef enum {
    EMPTY,
    FILLED,
    DELETED
} EntryState;

/* Hash table entry */
typedef struct {
    char *key;
    void *value;
    EntryState state;
} HashEntry;

/* Hash table structure */
typedef struct {
    HashEntry *entries;
    size_t capacity;
    size_t size;
    float load_factor;
} HashTable;

/* Hash function using djb2 algorithm */
static size_t hash_function(const char *key, size_t capacity) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c;  /* hash * 33 + c */
    }

    return hash % capacity;
}

/* Resize the hash table */
static void resize(HashTable *table, size_t new_capacity) {
    HashEntry *old_entries = table->entries;
    size_t old_capacity = table->capacity;

    table->entries = (HashEntry *)calloc(new_capacity, sizeof(HashEntry));
    table->capacity = new_capacity;
    table->size = 0;

    /* Rehash all existing entries */
    for (size_t i = 0; i < old_capacity; i++) {
        if (old_entries[i].state == FILLED) {
            hash_table_set(table, old_entries[i].key, old_entries[i].value);
            free(old_entries[i].key);  /* Free the old key since we copied it */
        } else {
            free(old_entries[i].key);  /* Free any keys in DELETED entries too */
        }
    }

    free(old_entries);
}

/* Create a new hash table */
HashTable *hash_table_create(size_t initial_capacity) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    if (!table) {
        return NULL;
    }

    table->capacity = initial_capacity;
    table->size = 0;
    table->load_factor = 0.7;
    table->entries = (HashEntry *)calloc(table->capacity, sizeof(HashEntry));

    if (!table->entries) {
        free(table);
        return NULL;
    }

    return table;
}

/* Set a key-value pair in the hash table */
void hash_table_set(HashTable *table, const char *key, void *value) {
    if (!table || !key) {
        return;
    }

    /* Check if we need to resize */
    if ((float)(table->size + 1) / table->capacity > table->load_factor) {
        size_t new_capacity = table->capacity * 2;
        resize(table, new_capacity);
    }

    size_t index = hash_function(key, table->capacity);
    size_t original_index = index;
    size_t i = 0;

    /* Linear probing for empty slot or existing key */
    while (table->entries[index].state == FILLED && 
           strcmp(table->entries[index].key, key) != 0) {
        index = (original_index + ++i) % table->capacity;

        /* Prevent infinite loop in case of table being full */
        if (i >= table->capacity) {
            return;
        }
    }

    /* If key exists, update value */
    if (table->entries[index].state == FILLED) {
        table->entries[index].value = value;
    } else {
        /* New entry */
        table->entries[index].key = strdup(key);
        table->entries[index].value = value;
        table->entries[index].state = FILLED;
        table->size++;
    }
}

/* Get a value by key */
void *hash_table_get(HashTable *table, const char *key) {
    if (!table || !key) {
        return NULL;
    }

    size_t index = hash_function(key, table->capacity);
    size_t original_index = index;
    size_t i = 0;

    while (table->entries[index].state != EMPTY && i < table->capacity) {
        if (table->entries[index].state == FILLED && 
            strcmp(table->entries[index].key, key) == 0) {
            return table->entries[index].value;
        }
        index = (original_index + ++i) % table->capacity;
    }

    return NULL;  /* Key not found */
}

/* Delete a key-value pair (marks entry as deleted) */
void hash_table_delete(HashTable *table, const char *key) {
    if (!table || !key) {
        return;
    }

    size_t index = hash_function(key, table->capacity);
    size_t original_index = index;
    size_t i = 0;

    while (table->entries[index].state != EMPTY && i < table->capacity) {
        if (table->entries[index].state == FILLED && 
            strcmp(table->entries[index].key, key) == 0) {

            /* Mark as deleted instead of removing */
            free(table->entries[index].key);
            table->entries[index].key = NULL;
            table->entries[index].state = DELETED;
            table->size--;
            return;
        }
        index = (original_index + ++i) % table->capacity;
    }
}

/* Destroy the hash table and free all memory */
void hash_table_destroy(HashTable *table) {
    if (!table) {
        return;
    }

    for (size_t i = 0; i < table->capacity; i++) {
        if (table->entries[i].state == FILLED) {
            free(table->entries[i].key);
            /* Note: We don't free the value because we don't know its type */
        }
    }

    free(table->entries);
    free(table);
}

/* Example usage and test */
int main() {
    HashTable *table = hash_table_create(16);

    /* Set some values */
    int val1 = 100;
    int val2 = 200;
    int val3 = 300;
    char *str_val = "Hello World";

    hash_table_set(table, "key1", &val1);
    hash_table_set(table, "key2", &val2);
    hash_table_set(table, "key3", &val3);
    hash_table_set(table, "string_key", str_val);

    /* Get values */
    int *retrieved1 = (int *)hash_table_get(table, "key1");
    int *retrieved2 = (int *)hash_table_get(table, "key2");
    char *retrieved3 = (char *)hash_table_get(table, "string_key");

    if (retrieved1) printf("key1: %d\n", *retrieved1);
    if (retrieved2) printf("key2: %d\n", *retrieved2);
    if (retrieved3) printf("string_key: %s\n", retrieved3);

    /* Update existing key */
    int new_val = 150;
    hash_table_set(table, "key1", &new_val);
    retrieved1 = (int *)hash_table_get(table, "key1");
    if (retrieved1) printf("key1 updated: %d\n", *retrieved1);

    /* Delete a key */
    hash_table_delete(table, "key2");
    retrieved2 = (int *)hash_table_get(table, "key2");
    printf("key2 after deletion: %s\n", retrieved2 ? "exists" : "not found");

    /* Test rehashing (insert many values) */
    for (int i = 0; i < 100; i++) {
        char key[32];
        snprintf(key, sizeof(key), "test_key_%d", i);
        int *val = (int *)malloc(sizeof(int));
        *val = i * 10;
        hash_table_set(table, key, val);
    }

    printf("Table size after inserting 100 values: %zu\n", table->size);

    /* Clean up */
    /* Note: In a real application, you'd need to free all allocated values */
    hash_table_destroy(table);

    return 0;
}
```

## Key Features:

1. **Open Addressing with Linear Probing**:
   - When collisions occur, we probe sequentially through the table
   - Uses a `state` field (EMPTY, FILLED, DELETED) to handle deletions properly

2. **Dynamic Resizing**:
   - Automatically resizes when load factor exceeds 70%
   - Rehashes all existing entries to maintain performance

3. **Complete API**:
   - `hash_table_create`: Creates a new hash table with specified initial capacity
   - `hash_table_set`: Inserts or updates a key-value pair
   - `hash_table_get`: Retrieves a value by key (returns NULL if not found)
   - `hash_table_delete`: Marks an entry as deleted (lazy deletion)
   - `hash_table_destroy`: Frees all memory

4. **String Keys and Void* Values**:
   - Keys are duplicated (using `strdup`) so caller doesn't need to manage memory
   - Values are stored as `void*` (caller manages value memory)

5. **Efficient Hash Function**:
   - Uses djb2 algorithm which provides good distribution for strings

## Important Notes:

- **Memory Management**: The hash table doesn't free `void*` values since it doesn't know their type. You'll need to free them separately before destroying the table.
- **Deleted Entries**: Uses lazy deletion (marks entries as DELETED) to maintain probe sequences.
- **Thread Safety**: This implementation is not thread-safe. For concurrent use, you'd need to add synchronization.
- **Performance**: Average case O(1) for set/get/delete operations, worst case O(n) when many collisions occur.

