/**
 * @brief Multiplies a row-major float matrix by a float vector.
 * 
 * This function computes y = A * x, where:
 *   - A is an m × n matrix stored in row-major order,
 *   - x is an n-dimensional vector,
 *   - y is an m-dimensional result vector.
 * 
 * The loop order is chosen for cache-friendly access. In row-major storage,
 * elements within a row are contiguous in memory. By placing the column
 * index `j` in the inner loop, we scan each row of A sequentially, which
 * maximizes spatial locality and allows efficient use of cache lines.
 * 
 * @param A  Pointer to the input matrix (row-major, size m × n).
 * @param x  Pointer to the input vector (size n).
 * @param y  Pointer to the output vector (size m). Must not overlap with A or x.
 * @param m  Number of rows in A (and length of y).
 * @param n  Number of columns in A (and length of x).
 */
void matrix_vector_multiply(const float* A, const float* x, float* y, int m, int n) {
    // Outer loop iterates over rows of A.
    for (int i = 0; i < m; ++i) {
        float sum = 0.0f;
        // Inner loop iterates over columns of A and elements of x.
        // This accesses A[i * n + j] sequentially, which is cache-friendly
        // because consecutive memory accesses are to adjacent matrix elements.
        for (int j = 0; j < n; ++j) {
            sum += A[i * n + j] * x[j];
        }
        y[i] = sum;
    }
}
