Here's a minimal, clean, and working thread pool skeleton using `pthreads`. It includes:

* A fixed number of worker threads
* A task queue protected by a mutex
* A condition variable for idle workers and shutdown signaling
* `pool_submit()` to add work
* `pool_shutdown()` to gracefully stop everything

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

/* -------------------------------------------------------------
 * Task: a unit of work — a function pointer + argument
 * ------------------------------------------------------------- */
typedef void (*task_func_t)(void *arg);

struct task {
    task_func_t    func;   /* function to call */
    void          *arg;    /* argument to pass to func */
    struct task   *next;   /* linked-list chain */
};

/* -------------------------------------------------------------
 * Thread pool state
 * ------------------------------------------------------------- */
struct thread_pool {
    int               shutdown;     /* 1 once pool is shutting down */
    int               num_threads;  /* how many workers */
    pthread_t        *threads;      /* array of pthread_t */
    pthread_mutex_t   lock;         /* protects queue + shutdown flag */
    pthread_cond_t    cond;         /* signaled when task arrives or shutdown */
    struct task      *queue;        /* head of the task queue */
};

/* -------------------------------------------------------------
 * worker_routine: what each worker thread runs
 * ------------------------------------------------------------- */
void *worker_routine(void *arg) {
    struct thread_pool *pool = (struct thread_pool *)arg;

    for (;;) {
        pthread_mutex_lock(&pool->lock);

        /* Wait until there's a task OR the pool is shutting down */
        while (pool->queue == NULL && !pool->shutdown) {
            pthread_cond_wait(&pool->cond, &pool->lock);
        }

        /* If shutting down AND queue is empty, exit the thread */
        if (pool->shutdown && pool->queue == NULL) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }

        /* Otherwise, pop the head task */
        struct task *task = pool->queue;
        pool->queue = task->next;
        pthread_mutex_unlock(&pool->lock);

        /* Execute the task outside the lock */
        if (task->func) {
            task->func(task->arg);
        }
        free(task);   /* optional: return memory to pool */
    }
    return NULL;
}

/* -------------------------------------------------------------
 * pool_create: allocate and start the thread pool
 * ------------------------------------------------------------- */
struct thread_pool *pool_create(int num_threads) {
    struct thread_pool *pool = 
        (struct thread_pool *)calloc(1, sizeof(struct thread_pool));
    if (!pool) return NULL;

    pool->num_threads = num_threads;
    pool->shutdown    = 0;
    pool->queue       = NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);

    pool->threads = (pthread_t *)malloc(num_threads * sizeof(pthread_t));
    if (!pool->threads) {
        free(pool);
        return NULL;
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_create(&pool->threads[i], NULL, worker_routine, pool);
    }
    return pool;
}

/* -------------------------------------------------------------
 * pool_submit: add a callable task to the queue
 * Returns 0 on success, -1 on failure
 * ------------------------------------------------------------- */
int pool_submit(struct thread_pool *pool, task_func_t func, void *arg) {
    if (!pool || pool->shutdown) return -1;

    struct task *task = (struct task *)malloc(sizeof(struct task));
    if (!task) return -1;

    task->func   = func;
    task->arg    = arg;
    task->next   = NULL;   /* push-to-front (head) */

    pthread_mutex_lock(&pool->lock);
    /* Simple head-insert; could be tail-insert for FIFO */
    task->next = pool->queue;
    pool->queue   = task;

    /* Wake up one waiting worker */
    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

/* -------------------------------------------------------------
 * pool_shutdown: ask workers to stop, wake them, and join them
 * ------------------------------------------------------------- */
void pool_shutdown(struct thread_pool *pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);
    pool->shutdown = 1;
    /* Wake ALL waiting workers so they can check the shutdown flag */
    pthread_cond_broadcast(&pool->cond);
    pthread_mutex_unlock(&pool->lock);

    /* Wait for every worker thread to finish */
    for (int i = 0; i < pool->num_threads; i++) {
        pthread_join(pool->threads[i], NULL);
    }
}

/* -------------------------------------------------------------
 * example task function (just for demonstration)
 * ------------------------------------------------------------- */
void example_task(void *arg) {
    int id = *(int *)arg;
    printf("Worker %d: executing task\n", id);
    /* simulate work */
    for (volatile int k = 0; k < 1000000; k++);
}

/* -------------------------------------------------------------
 * minimal main to show it all fits together
 * ------------------------------------------------------------- */
int main(void) {
    struct thread_pool *pool = pool_create(4);   /* 4 worker threads */

    int args[4] = {1, 2, 3, 4};
    for (int i = 0; i < 8; i++) {
        pool_submit(pool, example_task, &args[i % 4]);
    }

    /* Let tasks run a bit, then shut down cleanly */
    /* In a real app you'd have some condition-based trigger */
    sleep(2);   /* just enough for queued tasks to start */
    pool_shutdown(pool);

    printf("Pool shut down cleanly.\n");
    return 0;
}
```

### Key Design Points
| Component | Purpose |
|---|---|
| `pool->lock` | Protects the task queue head and the `shutdown` flag. All queue mutations and condition waits happen inside this mutex. |
| `pool->cond` | Workers `wait` on it when the queue is empty. `pool_submit` signals it (`signal` wakes one; `broadcast` wakes all, used on shutdown). |
| Worker loop | `while (queue == NULL && !shutdown)` handles spurious wakeups and ensures workers only exit when both conditions are met. |
| `pool_shutdown` | Sets the flag, broadcasts to rouse every blocked worker, then joins all threads. After this call, the pool is fully drained and terminated. |
| Task execution | Happens **outside** the mutex so other tasks can be queued/extracted concurrently. The popped node is freed after execution. |

This compiles with `gcc -pthread pool_skeleton.c -o pool_skeleton` and demonstrates a complete, race-free thread‑pool skeleton using only the POSIX threading API.

