typedef enum {
    HEADER_SUCCESS = 0,
    HEADER_ERROR_READ_FAILED,
    HEADER_ERROR_MAGIC_MISMATCH,
    HEADER_ERROR_ENDIANNES_MISMATCH,
    HEADER_ERROR_INVALID_VERSION,
    HEADER_ERROR_INVALID_COUNT
} HeaderError;

/* Binary file header structure */
typedef struct {
    uint32_t magic;      /* 4 bytes: File signature */
    uint32_t version;    /* 4 bytes: Format version */
    uint64_t count;      /* 8 bytes: Entry count */
} FileHeader;

