HeaderError parse_header(FILE *file, FileHeader *header, bool *is_little_endian);
const char* get_error_message(HeaderError error);
void print_header(const FileHeader *header, bool is_little_endian);

/* Utility functions for endianness */
static inline uint32_t swap_uint32(uint32_t val) {
    return ((val & 0xFF) << 24) |
           ((val & 0xFF00) << 8) |
           ((val >> 8) & 0xFF00) |
           ((val >> 24) & 0xFF);
}

static inline uint64_t swap_uint64(uint64_t val) {
    return ((val & 0x00000000000000FFULL) << 56) |
           ((val & 0x000000000000FF00ULL) << 40) |
           ((val & 0x0000000000FF0000ULL) << 24) |
           ((val & 0x00000000FF000000ULL) << 8) |
           ((val & 0x000000FF00000000ULL) >> 8) |
           ((val & 0x0000FF0000000000ULL) >> 24) |
           ((val & 0x00FF000000000000ULL) >> 40) |
           ((val & 0xFF00000000000000ULL) >> 56);
}

/* Check host endianness */
static inline bool is_host_little_endian(void) {
    const uint16_t one = 1;
    return (*(const uint8_t*)&one) == 1;
}

/**
 * Parse a binary file header with endianness detection and validation.
 * 
 * @param file: Open file positioned at start of header
 * @param header: Output structure for parsed header
 * @param is_little_endian: Output flag indicating file endianness
 * @return: HEADER_SUCCESS on success, error code otherwise
 */
HeaderError parse_header(FILE *file, FileHeader *header, bool *is_little_endian) {
    if (!file || !header || !is_little_endian) {
        return HEADER_ERROR_READ_FAILED;
    }

    /* Read raw bytes for magic number to detect endianness */
    uint32_t raw_magic;
    if (fread(&raw_magic, sizeof(uint32_t), 1, file) != 1) {
        return HEADER_ERROR_READ_FAILED;
    }

    /* Check both endianness possibilities for magic */
    bool file_is_little_endian;
    if (raw_magic == HEADER_MAGIC_LE) {
        file_is_little_endian = true;
    } else if (raw_magic == HEADER_MAGIC) {
        file_is_little_endian = false;
    } else {
        return HEADER_ERROR_MAGIC_MISMATCH;
    }

    /* Set header magic based on detected endianness */
    header->magic = HEADER_MAGIC;
    *is_little_endian = file_is_little_endian;

    /* Read and convert version (4 bytes) */
    uint32_t raw_version;
    if (fread(&raw_version, sizeof(uint32_t), 1, file) != 1) {
        return HEADER_ERROR_READ_FAILED;
    }

    /* Convert to host endianness if needed */
    if (is_host_little_endian() != file_is_little_endian) {
        raw_version = swap_uint32(raw_version);
    }

    /* Validate version range (common check) */
    if (raw_version == 0 || raw_version > 1000) {
        return HEADER_ERROR_INVALID_VERSION;
    }
    header->version = raw_version;

    /* Read and convert count (8 bytes) */
    uint64_t raw_count;
