/**
 * Get human-readable error message for header parsing error.
 */
const char* get_error_message(HeaderError error) {
    switch (error) {
        case HEADER_SUCCESS:
            return "Header parsed successfully";
        case HEADER_ERROR_READ_FAILED:
            return "Failed to read header from file";
        case HEADER_ERROR_MAGIC_MISMATCH:
            return "Magic number mismatch (expected 'MHDR')";
        case HEADER_ERROR_ENDIANNES_MISMATCH:
            return "Endianness conversion error";
        case HEADER_ERROR_INVALID_VERSION:
            return "Invalid version number";
        case HEADER_ERROR_INVALID_COUNT:
            return "Invalid count value";
        default:
