#include <stdint.h>
#include <stddef.h>
#include <string.h>

// Maximum valid Unicode code point
#define MAX_CODE_POINT 0x10FFFF

// UTF-8 replacement character for errors
#define REPLACEMENT_CHAR 0xFFFD

/**
 * Decode a single UTF-8 sequence to a UTF-32 code point
 * 
 * @param utf8        Input UTF-8 string
 * @param length      Length of the UTF-8 string in bytes
 * @param bytes_read  Output: number of bytes consumed
 * 
 * @return UTF-32 code point, or REPLACEMENT_CHAR on error
 */
uint32_t utf8_to_utf32(const char *utf8, size_t length, size_t *bytes_read)
{
    if (utf8 == NULL || length == 0 || bytes_read == NULL) {
        if (bytes_read) *bytes_read = 0;
        return REPLACEMENT_CHAR;
    }

    const unsigned char *data = (const unsigned char *)utf8;
    size_t consumed = 0;
    uint32_t codepoint = 0;

    // Determine sequence length from first byte
    if (data[0] <= 0x7F) {
        // 1-byte sequence (ASCII)
        codepoint = data[0];
        consumed = 1;
    }
    else if ((data[0] & 0xE0) == 0xC0) {
        // 2-byte sequence
        consumed = 2;
        if (length < consumed) goto error;

        // Check for overlong encoding (would encode < 0x80)
        if ((data[0] & 0x1E) == 0) goto error;

        // Validate continuation byte
        if ((data[1] & 0xC0) != 0x80) goto error;

        codepoint = (data[0] & 0x1F) << 6 |
                    (data[1] & 0x3F);
    }
    else if ((data[0] & 0xF0) == 0xE0) {
        // 3-byte sequence
        consumed = 3;
        if (length < consumed) goto error;

        // Check for overlong encoding (would encode < 0x800)
        if (data[0] == 0xE0 && (data[1] & 0x20) == 0) goto error;

        // Check for surrogate halves (U+D800..U+DFFF)
        if (data[0] == 0xE0 && data[1] >= 0xA0 && data[1] <= 0xBF) {
            if (data[2] >= 0x80 && data[2] <= 0xBF) goto error;
        }

        // Validate continuation bytes
        if ((data[1] & 0xC0) != 0x80 || (data[2] & 0xC0) != 0x80) goto error;

        codepoint = (data[0] & 0x0F) << 12 |
                    (data[1] & 0x3F) << 6 |
                    (data[2] & 0x3F);
    }
    else if ((data[0] & 0xF8) == 0xF0) {
        // 4-byte sequence
        consumed = 4;
        if (length < consumed) goto error;

        // Check for overlong encoding (would encode < 0x10000)
        if (data[0] == 0xF0 && (data[1] & 0x30) == 0) goto error;

        // Check if code point exceeds Unicode range (> U+10FFFF)
        if (data[0] > 0xF4) goto error;
        if (data[0] == 0xF4 && data[1] > 0x8F) goto error;

        // Validate continuation bytes
        if ((data[1] & 0xC0) != 0x80 || 
            (data[2] & 0xC0) != 0x80 || 
            (data[3] & 0xC0) != 0x80) goto error;

        codepoint = (data[0] & 0x07) << 18 |
                    (data[1] & 0x3F) << 12 |
                    (data[2] & 0x3F) << 6 |
                    (data[3] & 0x3F);
    }
    else {
        // Invalid start byte
        goto error;
    }

    // Final range check
    if (codepoint > MAX_CODE_POINT) goto error;

    *bytes_read = consumed;
    return codepoint;

error:
    // Consume one byte for the invalid start and return replacement char
    *bytes_read = 1;
    return REPLACEMENT_CHAR;
}

/**
 * Encode a UTF-32 code point to UTF-8
 * 
 * @param codepoint   UTF-32 code point to encode
 * @param utf8        Output buffer
 * @param buf_size    Size of output buffer in bytes
 * 
 * @return Number of bytes written, or 0 on error
 */
size_t utf32_to_utf8(uint32_t codepoint, char *utf8, size_t buf_size)
{
    if (utf8 == NULL || buf_size == 0) {
        return 0;
    }

    // Check for invalid code points
    if (codepoint > MAX_CODE_POINT ||
        (codepoint >= 0xD800 && codepoint <= 0xDFFF)) {
        codepoint = REPLACEMENT_CHAR;
