 * 
 * @param buffer    Input byte buffer
 * @param buf_len   Length of the buffer in bytes
 * @param offset    Pointer to current offset in buffer (updated on success)
 * @param uint64_val Pointer to store the read uint64 value
 * @param varint_val Pointer to store the read varint value
 * @return READ_SUCCESS on success, negative error code on failure
 */
ReadResult read_uint64_and_varint(
    const uint8_t* buffer,
    size_t buf_len,
    size_t* offset,
    uint64_t* uint64_val,
    uint64_t* varint_val
) {
    // Check if we have enough data for uint64 (8 bytes minimum)
    if (*offset + sizeof(uint64_t) > buf_len) {
        return READ_INSUFFICIENT_DATA;
    }

    // Read uint64 in little-endian format
    uint64_t result = 0;
    for (int i = 0; i < 8; i++) {
        result |= (uint64_t)buffer[*offset + i] << (i * 8);
    }
    *offset += 8;

    if (uint64_val != NULL) {
        *uint64_val = result;
    }

    // Read varint
    uint64_t varint_result = 0;
    int shift = 0;
    size_t varint_start = *offset;

    while (*offset < buf_len) {
        uint8_t byte = buffer[*offset];
        (*offset)++;

        varint_result |= (uint64_t)(byte & 0x7F) << shift;

        if ((byte & 0x80) == 0) {
            // MSB is 0, so this is the last byte
            if (varint_val != NULL) {
                *varint_val = varint_result;
            }
            return READ_SUCCESS;
        }

        shift += 7;

        // Check if varint is too long (more than 10 bytes for 64-bit value)
        if (shift > 63) {
            return READ_VARINT_TOO_LONG;
        }
    }

    // If we get here, we ran out of buffer before finding end of varint
    return READ_INSUFFICIENT_DATA;
}
