Here's a minimal JSON tokenizer in C with no dependencies:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    TOKEN_OBJECT_START,
    TOKEN_OBJECT_END,
    TOKEN_ARRAY_START,
    TOKEN_ARRAY_END,
    TOKEN_COLON,
    TOKEN_COMMA,
    TOKEN_STRING,
    TOKEN_NUMBER,
    TOKEN_TRUE,
    TOKEN_FALSE,
    TOKEN_NULL,
    TOKEN_END,
    TOKEN_ERROR
} TokenType;

typedef struct {
    TokenType type;
    int start;
    int length;
} Token;

typedef struct {
    Token* tokens;
    int capacity;
    int count;
    const char* input;
    int position;
} Tokenizer;

void init_tokenizer(Tokenizer* tokenizer, const char* json) {
    tokenizer->input = json;
    tokenizer->position = 0;
    tokenizer->capacity = 64;
    tokenizer->count = 0;
    tokenizer->tokens = malloc(sizeof(Token) * tokenizer->capacity);
}

void add_token(Tokenizer* tokenizer, TokenType type, int start, int length) {
    if (tokenizer->count >= tokenizer->capacity) {
        tokenizer->capacity *= 2;
        tokenizer->tokens = realloc(tokenizer->tokens, sizeof(Token) * tokenizer->capacity);
    }

    tokenizer->tokens[tokenizer->count].type = type;
    tokenizer->tokens[tokenizer->count].start = start;
    tokenizer->tokens[tokenizer->count].length = length;
    tokenizer->count++;
}

int skip_whitespace(Tokenizer* tokenizer) {
    int count = 0;
    char c;
    while ((c = tokenizer->input[tokenizer->position]) == ' ' || 
           c == '\t' || c == '\n' || c == '\r') {
        tokenizer->position++;
        count++;
    }
    return count;
}

int tokenize_string(Tokenizer* tokenizer) {
    int start = tokenizer->position;
    int length = 0;
    char c;

    tokenizer->position++; // skip opening quote

    while ((c = tokenizer->input[tokenizer->position]) != '\0') {
        if (c == '\\') {
            tokenizer->position++; // skip escape character
            if (tokenizer->input[tokenizer->position] == '\0') {
                return -1; // Error
            }
        } else if (c == '"') {
            tokenizer->position++; // skip closing quote
            length = tokenizer->position - start;
            return length;
        }
        tokenizer->position++;
    }

    return -1; // Error - unterminated string
}

int tokenize_number(Tokenizer* tokenizer) {
    int start = tokenizer->position;
    char c;

    // Handle optional negative sign
    if ((c = tokenizer->input[tokenizer->position]) == '-') {
        tokenizer->position++;
    }

    // Integer part
    if ((c = tokenizer->input[tokenizer->position]) == '0') {
        tokenizer->position++;
    } else if (c >= '1' && c <= '9') {
        while ((c = tokenizer->input[tokenizer->position]) >= '0' && c <= '9') {
            tokenizer->position++;
        }
    } else {
        return -1; // Error - invalid number
    }

    // Fractional part (optional)
    if ((c = tokenizer->input[tokenizer->position]) == '.') {
        tokenizer->position++;
        if ((c = tokenizer->input[tokenizer->position]) < '0' || c > '9') {
            return -1; // Error
        }
        while ((c = tokenizer->input[tokenizer->position]) >= '0' && c <= '9') {
            tokenizer->position++;
        }
    }

    // Exponent part (optional)
    if ((c = tokenizer->input[tokenizer->position]) == 'e' || c == 'E') {
        tokenizer->position++;
        if ((c = tokenizer->input[tokenizer->position]) == '+' || c == '-') {
            tokenizer->position++;
        }
        if ((c = tokenizer->input[tokenizer->position]) < '0' || c > '9') {
            return -1; // Error
        }
        while ((c = tokenizer->input[tokenizer->position]) >= '0' && c <= '9') {
            tokenizer->position++;
        }
    }

    return tokenizer->position - start;
}

int tokenize_keyword(Tokenizer* tokenizer, const char* keyword, int keyword_length, TokenType type) {
    if (strncmp(tokenizer->input + tokenizer->position, keyword, keyword_length) == 0) {
        tokenizer->position += keyword_length;
        return keyword_length;
    }
    return -1;
}

Token* tokenize_json(const char* json, int* token_count) {
    Tokenizer tokenizer;
    init_tokenizer(&tokenizer, json);

    while (tokenizer.input[tokenizer.position] != '\0') {
        skip_whitespace(&tokenizer);

        if (tokenizer.input[tokenizer.position] == '\0') {
            break;
        }

        char c = tokenizer.input[tokenizer.position];
        int start = tokenizer.position;
        int length;

        if (c == '{') {
            add_token(&tokenizer, TOKEN_OBJECT_START, start, 1);
            tokenizer.position++;
        } else if (c == '}') {
            add_token(&tokenizer, TOKEN_OBJECT_END, start, 1);
            tokenizer.position++;
        } else if (c == '[') {
            add_token(&tokenizer, TOKEN_ARRAY_START, start, 1);
            tokenizer.position++;
        } else if (c == ']') {
            add_token(&tokenizer, TOKEN_ARRAY_END, start, 1);
            tokenizer.position++;
        } else if (c == ':') {
            add_token(&tokenizer, TOKEN_COLON, start, 1);
            tokenizer.position++;
        } else if (c == ',') {
            add_token(&tokenizer, TOKEN_COMMA, start, 1);
            tokenizer.position++;
        } else if (c == '"') {
            length = tokenize_string(&tokenizer);
            if (length != -1) {
                add_token(&tokenizer, TOKEN_STRING, start, length);
            } else {
                add_token(&tokenizer, TOKEN_ERROR, start, tokenizer.position - start);
                break;
            }
        } else if (c == '-' || (c >= '0' && c <= '9')) {
            length = tokenize_number(&tokenizer);
            if (length != -1) {
                add_token(&tokenizer, TOKEN_NUMBER, start, length);
            } else {
                add_token(&tokenizer, TOKEN_ERROR, start, tokenizer.position - start);
                break;
            }
        } else if (strncmp(tokenizer.input + tokenizer.position, "true", 4) == 0) {
            length = tokenize_keyword(&tokenizer, "true", 4, TOKEN_TRUE);
            add_token(&tokenizer, TOKEN_TRUE, start, length);
        } else if (strncmp(tokenizer.input + tokenizer.position, "false", 5) == 0) {
            length = tokenize_keyword(&tokenizer, "false", 5, TOKEN_FALSE);
            add_token(&tokenizer, TOKEN_FALSE, start, length);
        } else if (strncmp(tokenizer.input + tokenizer.position, "null", 4) == 0) {
            length = tokenize_keyword(&tokenizer, "null", 4, TOKEN_NULL);
            add_token(&tokenizer, TOKEN_NULL, start, length);
        } else {
            add_token(&tokenizer, TOKEN_ERROR, start, 1);
            tokenizer.position++;
            break;
        }
    }

    add_token(&tokenizer, TOKEN_END, tokenizer.position, 0);
    *token_count = tokenizer.count;
    return tokenizer.tokens;
}

void free_tokens(Token* tokens) {
    free(tokens);
}

// Example usage
int main() {
    const char* json = "{\"name\": \"John\", \"age\": 30, \"is_student\": false, \"courses\": [\"Math\", \"Science\"]}";
    int token_count;

    Token* tokens = tokenize_json(json, &token_count);

    printf("Token count: %d\n", token_count);
    printf("Tokens:\n");

    for (int i = 0; i < token_count; i++) {
        printf("Token %d: type=%d, start=%d, length=%d", 
               i, tokens[i].type, tokens[i].start, tokens[i].length);

        // Print the actual token text
        if (tokens[i].length > 0) {
            printf(" -> \"");
            for (int j = tokens[i].start; j < tokens[i].start + tokens[i].length; j++) {
                putchar(json[j]);
            }
            printf("\"");
        }
        printf("\n");
    }

    free_tokens(tokens);
    return 0;
}
```

**Key Features:**

1. **Token Types:** Supports all basic JSON tokens - objects, arrays, strings, numbers, booleans, null, and structural characters.

